// ─── ADD FIRST ITEM ───────────────────────────────────────────
cy.xpath(_Selector.selectors.dogs_ctgry).click();
cy.xpath(_Selector.selectors.bulldog_productid).click();
cy.contains('Add to Cart').should('be.visible');
cy.xpath(_Selector.selectors.male_adult_bulldog_cart_btn).click();
cy.contains('Male Adult Bulldog').should('be.visible');
// ─── ADD SECOND ITEM ──────────────────────────────────────────
cy.xpath(_Selector.selectors.return_to_main_menu_btn).click();
cy.xpath(_Selector.selectors.fish_ctgry).click();
cy.xpath(_Selector.selectors.goldfish_productid).click();
cy.contains('Add to Cart').should('be.visible');
cy.xpath(_Selector.selectors.adult_female_goldfish_cart_btn).click();
cy.contains('Adult Female Goldfish').should('be.visible');
// ─── ADD THIRD ITEM ───────────────────────────────────────────
cy.xpath(_Selector.selectors.return_to_main_menu_btn).click();
cy.xpath(_Selector.selectors.fish_ctgry).click();
cy.xpath(_Selector.selectors.angelfish_productid).click();
cy.contains('Add to Cart').should('be.visible');
cy.xpath(_Selector.selectors.small_angelfish_cart_btn).click();
cy.contains('Small Angelfish').should('be.visible');
// ─── ASSERT ALL 3 ITEMS IN CART ───────────────────────────────
cy.xpath(_Selector.selectors.cart_body).within(() => {
  cy.contains('Male Adult Bulldog').should('be.visible');
  cy.contains('Adult Female Goldfish').should('be.visible');
  cy.contains('Small Angelfish').should('be.visible');
});
// ─── REMOVE ONE ITEM ──────────────────────────────────────────
// cy.xpath(selectors.cart_body).should('contain.text', 'Remove');
cy.xpath(_Selector.selectors.small_angelfish_remove_btn).click();
cy.log("Small Angelfish removed");
// ─── REMOVE ALL ITEMS ─────────────────────────────────────────
cy.xpath(_Selector.selectors.cart_body).should('contain.text', 'Remove All');
cy.xpath(_Selector.selectors.remove_all_btn).click();
cy.log("All items removed from cart");
